Here's how to handle each scenario with modern MSTest (3.9+):

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class MyTests
{
    private string? _tempFile;

    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        // Skipped automatically on non-Windows
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Setting", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void RenderFrame_ProducesValidOutput()
    {
        // Skipped when running in CI environments
        var frame = GpuRenderer.RenderFrame();
        Assert.IsNotNull(frame);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var result = await _weatherClient.GetForecastAsync();
        Assert.IsNotNull(result);
    }

    // 4. Cleanup temp files even on failure
    [TestMethod]
    public void Export_CreatesValidFile()
    {
        _tempFile = Path.GetTempFileName();
        FileExporter.Export(_tempFile);
        Assert.IsTrue(File.Exists(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        // Runs after every test, even if it fails
        if (_tempFile is not null && File.Exists(_tempFile))
        {
            File.Delete(_tempFile);
        }
    }
}
```

**Summary of attributes:**

| Scenario | Attribute/Pattern |
|----------|-------------------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` (3.10+) |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` (3.10+) |
| Flaky retry | `[Retry(3)]` (3.9+) |
| Guaranteed cleanup | `[TestCleanup]` method |

**Key notes:**
- `[TestCleanup]` always runs after each test (pass or fail), making it ideal for resource cleanup.
- `[Retry]` should only be used for genuinely flaky external dependencies — not to mask race conditions.
- `[OSCondition]` and `[CICondition]` mark tests as *skipped* (not failed) when conditions aren't met.
